INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U1', 'The books that have changed me', 'When I was young, I did not like reading at all. To me, books were boring, and I spent all my free time on games. But things have changed a lot since then.

Two years ago, my aunt gave me a thick story book for my birthday. It was about a young boy and his adventures in a strange land. At first I put it on the shelf and forgot about it. One rainy afternoon, with nothing to do, I opened it. I could not stop. I read for three hours without moving.

Since that day, I have read more than a hundred books. I have travelled to faraway places, met brave heroes, and lived a thousand lives, all inside my own room. Books have taught me about history, science, and people''s hearts. They have made me a kinder and wiser person.

My friends often ask about my love of reading. I always give them the same answer. ''A good book is a good friend,'' I say. ''It has never let me down.''

I have not finished my journey yet. So many wonderful books are still waiting for me. And I have made myself a promise: I will keep reading for the rest of my life.', '书籍带来的改变(现在完成时·经历)', 207, 0, '[{"q": "How did the writer feel about reading when he was young?", "answer": "B", "options": ["He loved reading story books.", "He thought reading was boring.", "He read for three hours every day.", "He had no free time at all."], "explanation": "开头''I did not like reading at all. To me, books were boring''。"}, {"q": "What has the writer done since he got the book from his aunt?", "answer": "C", "options": ["He has stopped playing games forever.", "He has written a hundred books.", "He has read more than a hundred books.", "He has sold his story books."], "explanation": "''Since that day, I have read more than a hundred books''。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["Games are better than books.", "Aunts always give the best gifts.", "Reading has changed the writer''s life for the better.", "The writer wants to be a writer."], "explanation": "全文写阅读如何改变了''我'',使''我''更善良更有智慧。"}, {"q": "We can learn from the passage that the writer ____.", "answer": "A", "options": ["will go on reading in the future", "dislikes his aunt''s gift now", "reads only on rainy days", "has finished reading every book"], "explanation": "结尾''I will keep reading for the rest of my life''可推断他会继续阅读。"}, {"q": "In the passage, the sentence ''It has never let me down'' means a good book ____.", "answer": "A", "options": ["has never made him disappointed", "has never fallen on the floor", "is never heavy to carry", "has never been opened"], "explanation": "let sb down=让某人失望;此处指好书从未让''我''失望。"}]'::jsonb, '[{"word": "adventure", "cn": "冒险经历"}, {"word": "faraway", "cn": "遥远的"}, {"word": "wiser", "cn": "更有智慧的"}, {"word": "journey", "cn": "旅程"}, {"word": "hero", "cn": "英雄"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U1', 'Have you ever kept a pet?', 'Have you ever kept a pet? I have had a little cat called Mimi for three years. She has been my best friend since I was ten. I have learnt so much from her. She has taught me to be kind and patient. Every morning, she waits by my door, and I have never once forgotten to feed her. We have played together in the yard many times, and she has slept on my bed on cold nights. Mimi has grown bigger, but she is still full of joy. Some of my friends have never had a pet, and they do not know what they have missed. A pet is not just an animal; it has become a warm part of my family.', '你养过宠物吗(现在完成时·经历)', 123, 1, '[{"q": "How long has the writer had the cat Mimi?", "answer": "B", "options": ["One year.", "Three years.", "Five years.", "Ten years."], "explanation": "''I have had a little cat called Mimi for three years''。"}, {"q": "What has Mimi taught the writer?", "answer": "A", "options": ["To be kind and patient.", "To run fast.", "To cook well.", "To draw pictures."], "explanation": "''She has taught me to be kind and patient''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to feed a cat.", "Why cats sleep a lot.", "How a pet cat has become a warm part of the writer''s life.", "Where Mimi was born."], "explanation": "全文讲宠物如何成为生活温暖的一部分(完成时)。"}]'::jsonb, '[{"word": "pet", "cn": "宠物"}, {"word": "patient", "cn": "有耐心的"}, {"word": "feed", "cn": "喂养"}, {"word": "yard", "cn": "院子"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U1', 'My first time on a train', 'I have travelled by bus and by car many times, but I have never taken a long train ride until now. My family and I have just come back from a trip to the mountains, and I have so much to tell. I have never felt so excited as when the train began to move. Outside the window, green fields and small towns rushed by. I have seen many pictures of the countryside, but they have never looked so alive. During the ride, I have made a new friend, a boy of my own age. We have shared sweets and jokes for hours. The trip has ended, but the happy feeling has stayed with me. I have already asked my parents to plan another train trip soon.', '第一次坐火车(现在完成时·经历)', 127, 1, '[{"q": "Where has the writer''s family just come back from?", "answer": "D", "options": ["The sea.", "A big city.", "A farm.", "The mountains."], "explanation": "''My family and I have just come back from a trip to the mountains''。"}, {"q": "What did the writer do with the new friend during the ride?", "answer": "C", "options": ["Slept all the way.", "Read books alone.", "Shared sweets and jokes.", "Played on a phone."], "explanation": "''We have shared sweets and jokes for hours''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to buy a train ticket.", "Why buses are slow.", "Where the mountains are.", "The writer''s exciting first long train ride."], "explanation": "全文讲第一次长途火车之旅的兴奋(完成时)。"}]'::jsonb, '[{"word": "train", "cn": "火车"}, {"word": "excited", "cn": "兴奋的"}, {"word": "fields", "cn": "田野"}, {"word": "countryside", "cn": "乡村"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U1', 'The books I have read this year', 'This year, I have started a happy new habit: I have read one book every month. So far, I have finished ten books, and each one has opened a new world for me. I have laughed with funny stories and have cried with sad ones. One book has taught me about faraway places I have never seen. Another has helped me understand my own feelings. My reading has become faster, and my writing has become better too. My teacher has noticed the change and has smiled at me. Some friends have asked me how I find the time. I always tell them the same thing: I have simply turned off the screen and opened a book. Reading has given me more than any game ever has.', '今年我读过的书(现在完成时·经历)', 126, 1, '[{"q": "How many books has the writer finished so far this year?", "answer": "B", "options": ["Five.", "Ten.", "Twelve.", "Twenty."], "explanation": "''I have finished ten books''。"}, {"q": "What has become better besides the writer''s reading?", "answer": "A", "options": ["The writer''s writing.", "The writer''s cooking.", "The writer''s running.", "The writer''s drawing."], "explanation": "''my writing has become better too''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to write a book.", "Why games are fun.", "Where to buy books.", "How a reading habit has changed the writer for the better."], "explanation": "全文讲读书习惯带来的改变(完成时)。"}]'::jsonb, '[{"word": "habit", "cn": "习惯"}, {"word": "finished", "cn": "读完"}, {"word": "faraway", "cn": "遥远的"}, {"word": "screen", "cn": "屏幕"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U1', 'A hobby I have kept for years', 'I have kept the same hobby since I was seven: collecting stamps. My grandfather has loved stamps all his life, and he has given me my first small album. Since then, I have collected more than three hundred stamps from many countries. Each stamp has its own story. I have learnt about faraway lands, famous people and old buildings, all without leaving my desk. Collecting has taught me to be careful and patient. I have spent many quiet evenings sorting my stamps by colour and country. My friends have their own hobbies too; some have kept coins, others have grown plants. A good hobby has a quiet power: it has made my free time rich, and it has brought my grandfather and me closer than ever.', '我坚持多年的爱好(现在完成时·经历)', 126, 1, '[{"q": "Who gave the writer the first stamp album?", "answer": "C", "options": ["A teacher.", "A friend.", "The writer''s grandfather.", "A shopkeeper."], "explanation": "''he has given me my first small album''(grandfather)。"}, {"q": "How many stamps has the writer collected?", "answer": "A", "options": ["More than three hundred.", "About thirty.", "About one hundred.", "More than a thousand."], "explanation": "''I have collected more than three hundred stamps''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to buy stamps.", "A long-kept hobby that has enriched the writer''s life.", "Why coins are valuable.", "Where stamps come from."], "explanation": "全文讲多年爱好带来的丰盈(完成时)。"}]'::jsonb, '[{"word": "hobby", "cn": "爱好"}, {"word": "collecting", "cn": "收集"}, {"word": "stamps", "cn": "邮票"}, {"word": "album", "cn": "集邮册"}]'::jsonb);
-- U2 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U2', 'The old man and the bench', 'On a busy street stood a small shop. Outside it sat an old wooden bench. The bench has welcomed tired people for many years. Old men rested there in the sun. Children sat on it to eat their sweets. Mothers stopped to catch their breath. Everyone loved that friendly corner.

The shopkeeper, Mr Lang, grew selfish over time. ''This bench is mine,'' he said one morning. ''Why should strangers use it for free?'' He painted a hard sign and nailed it to the wall: NO SITTING. From that day, no one stopped at his corner any more.

Something strange happened. The street outside turned cold and quiet. Fewer people came to buy his bread. Mr Lang sat alone behind his counter, day after day, and his heart grew as hard as stone.

One winter evening, he saw a small girl by the wall, too tired and cold to walk home. For the first time in years, his heart softened. He carried the bench back out and gently helped her sit.

''Rest here, child,'' he said softly. ''This bench has always been for everyone.''

Slowly the people returned, and warm talk filled the corner again. Mr Lang has kept the bench outside since that night, and he has not felt lonely for a single day.', '分享与善良(现在完成时·since/for)·改写王尔德《自私的巨人》', 214, 0, '[{"q": "Why did people love the corner outside Mr Lang''s shop at first?", "answer": "B", "options": ["Because Mr Lang gave them free bread.", "Because the bench there welcomed tired people.", "Because the shop sold cheap sweets.", "Because the street was always warm."], "explanation": "开头长凳多年欢迎疲惫的人,大家喜欢那个友好的角落。"}, {"q": "What happened after Mr Lang put up the ''NO SITTING'' sign?", "answer": "D", "options": ["More people came to rest.", "The bench became newer.", "His bread sold better.", "No one stopped at his corner any more."], "explanation": "''From that day, no one stopped at his corner any more''。"}, {"q": "What does the story mainly tell us?", "answer": "C", "options": ["A shop should sell good bread.", "Old benches are hard to keep.", "Sharing and kindness bring warmth back to life.", "Winter is a cold and lonely season."], "explanation": "全文借长凳讲分享与善良让温暖回归。"}, {"q": "From ''his heart softened'', we can infer that Mr Lang ____.", "answer": "A", "options": ["began to feel kind again", "became ill that winter", "wanted to sell the bench", "was angry at the girl"], "explanation": "心软了→他重新变得善良,故carried the bench back。"}, {"q": "The underlined word ''selfish'' in the passage means ____.", "answer": "B", "options": ["kind and warm to everyone", "caring only about oneself", "tired and weak", "poor and hungry"], "explanation": "由他不许他人用长凳可推断selfish=只顾自己、自私。"}]'::jsonb, '[{"word": "bench", "cn": "长凳"}, {"word": "shopkeeper", "cn": "店主"}, {"word": "selfish", "cn": "自私的"}, {"word": "nailed", "cn": "钉(nail的过去式)"}, {"word": "counter", "cn": "柜台"}, {"word": "softened", "cn": "变软,软化"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U2', 'How our town has changed', 'Our small town has changed a lot in the last few years. When I was young, there was only one narrow road and a few old shops. Now the town has grown into a busy little place. A new park has been here since 2019, and children have come to play in it every day. The old wooden bridge has gone, and a strong new one has stood by the river for three years. My cousin has gone to the city for work, but my uncle has been to many places and still calls this town home. Some things, happily, have not changed. The tall old tree in the square still stands, and the morning market has kept its friendly voices for fifty years. I have grown up with it.', '我们的小镇变了(现在完成时·变化)', 129, 1, '[{"q": "How long has the new park been in the town?", "answer": "A", "options": ["Since 2019.", "Since last month.", "For fifty years.", "Since the writer was born."], "explanation": "''A new park has been here since 2019'';C 项 fifty years 是集市的年头,不是公园的。"}, {"q": "What has NOT changed in the town?", "answer": "D", "options": ["The old road.", "The wooden bridge.", "The small shops.", "The tall old tree in the square."], "explanation": "''The tall old tree in the square still stands''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How the writer''s town has changed over the years.", "How to build a bridge.", "Why parks are important.", "Where the market is."], "explanation": "全文讲小镇多年的变化(完成时)。"}]'::jsonb, '[{"word": "narrow", "cn": "狭窄的"}, {"word": "square", "cn": "广场"}, {"word": "market", "cn": "集市"}, {"word": "grown", "cn": "成长;发展(grow的过去分词)"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U2', 'I have grown taller', 'Something wonderful has happened: I have grown five centimetres in the last two years! Last summer, I could not reach the top shelf, but now I can take a book down with ease. My mother has measured me against the door, and the new mark is far above the old one. ''How long have you played basketball?'' she asked me last week. ''I have played it since I was eleven,'' I said. My shoes have become too small, and my trousers have grown too short. But growing up is more than growing tall. I have become stronger too, because I have played sport every week for two years. I have also grown braver: I have learnt to speak up in class. My grandmother has watched me change from a shy boy into a young man.', '我长高了(现在完成时·变化)', 135, 1, '[{"q": "How does the writer''s mother check his height?", "answer": "B", "options": ["With a ruler on the desk.", "By measuring him against the door.", "By asking the doctor.", "By looking at his shoes."], "explanation": "''My mother has measured me against the door''。"}, {"q": "Why has the writer become stronger?", "answer": "C", "options": ["Because he eats more.", "Because he sleeps more.", "Because he has played sport every week.", "Because he is taller."], "explanation": "''I have become stronger too, because I have played sport every week''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to buy new shoes.", "Why sport is hard.", "Where the writer lives.", "How the writer has grown, both tall and brave."], "explanation": "全文讲成长(身高+内心)(完成时)。"}]'::jsonb, '[{"word": "shelf", "cn": "架子"}, {"word": "measured", "cn": "量(measure的过去分词)"}, {"word": "mark", "cn": "记号"}, {"word": "braver", "cn": "更勇敢的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U2', 'Our class has become a team', 'At the start of this term, our class was just a group of strangers. We did not talk much, and we often quarrelled over small things. But a lot has happened since then, and we have changed into a real team. We have worked together on many projects, and we have learnt to listen to each other. When one classmate has felt sad, others have come to help. We have won a football match together, and we have shared both the joy and the hard work. Our teacher has watched us grow closer, and she has often smiled with pride. I have made friends here that I hope to keep for life. A class is not just a room full of desks; ours has become a warm second family.', '我们班成了一个团队(现在完成时·变化)', 129, 1, '[{"q": "What did the class often do at the start of the term?", "answer": "B", "options": ["Play games.", "Quarrel over small things.", "Sing together.", "Help each other."], "explanation": "''we often quarrelled over small things''。"}, {"q": "What have the classmates done when one has felt sad?", "answer": "A", "options": ["Come to help.", "Laughed at them.", "Left them alone.", "Told the teacher."], "explanation": "''When one classmate has felt sad, others have come to help''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to win a football match.", "Why desks are important.", "How a class has grown into a warm team.", "Where the classroom is."], "explanation": "全文讲班级如何成为团队(完成时)。"}]'::jsonb, '[{"word": "term", "cn": "学期"}, {"word": "strangers", "cn": "陌生人"}, {"word": "quarrelled", "cn": "争吵(quarrel的过去式)"}, {"word": "pride", "cn": "自豪"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U2', 'The river has come back to life', 'The small river behind our school has come back to life, and everyone is happy. A few years ago, it was full of rubbish, and no fish lived in it. The water turned dark, and it had a bad smell. Then our school started a clean-up club, and many students have joined it. We have picked up plastic bottles and old bags from the water. We have planted young trees along the bank. Slowly, the river has become clean again. This spring, small fish have returned, and birds have come to drink and sing. Even the air near the river has grown fresh. Our teacher has told us about the power of nature: it can heal itself, if only people give it a chance. Small hands can make a big change. We have all learnt this.', '小河重获新生(现在完成时·结果)', 137, 1, '[{"q": "What was the river full of a few years ago?", "answer": "A", "options": ["Rubbish.", "Fish.", "Boats.", "Flowers."], "explanation": "''it was full of rubbish, and no fish lived in it''。"}, {"q": "What has returned to the river this spring?", "answer": "B", "options": ["Boats.", "Small fish.", "Rubbish.", "Swimmers."], "explanation": "''small fish have returned''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to catch fish.", "Why plastic is cheap.", "Where the school is.", "How students have brought a dirty river back to life."], "explanation": "全文讲学生治理小河的成果(完成时)。"}]'::jsonb, '[{"word": "rubbish", "cn": "垃圾"}, {"word": "plastic", "cn": "塑料的"}, {"word": "bank", "cn": "河岸"}, {"word": "fresh", "cn": "清新的"}]'::jsonb);
-- U3 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U3', 'The boy who loved to invent', 'Ben was a curious boy who loved to make things. While other children enjoyed playing outside, he preferred sitting at his desk with wires, boxes, and old clocks. He wanted to build something useful, not just toys.

His grandmother lived with them. Her legs were weak, and carrying water up the stairs to her plants on the roof was hard for her. Ben decided to help. He planned to build a small machine to take the water up for her.

His first try failed. The machine dropped all the water on the floor. His second try failed too. It moved too fast and broke a pot. Ben''s friends told him to give up, but he refused to stop. ''Every failure teaches me something new,'' he said. He kept changing his design and testing it again and again.

After twenty tries, the little machine finally worked. It carried a cup of water slowly and safely up to the roof. His grandmother clapped her hands and started to cry with joy. Soon many neighbours came to see the little machine work, and everyone smiled at the boy with a proud look.

That evening, Ben wrote in his notebook: ''To invent is to fail, and to fail is to learn.'' He has never stopped inventing since then. He hopes to build machines to help many more people one day.', '发明与坚持(不定式/动名词作宾语)', 227, 0, '[{"q": "What did Ben prefer to do in his free time?", "answer": "B", "options": ["Playing outside with other children.", "Sitting at his desk making things.", "Watering the plants on the roof.", "Reading old story books."], "explanation": "''he preferred sitting at his desk with wires, boxes, and old clocks''。"}, {"q": "Why did Ben want to build the machine?", "answer": "C", "options": ["To win a school prize.", "To sell it for money.", "To help his grandmother take water up the stairs.", "To play a new game."], "explanation": "祖母腿脚弱,上楼浇花难,Ben decided to help,build a machine to take the water up。"}, {"q": "What is the best title''s idea of the passage?", "answer": "C", "options": ["Machines are dangerous to build.", "Grandmothers need a lot of help.", "Never give up, and failure can lead to success.", "Toys are better than real machines."], "explanation": "全文借Ben多次失败仍坚持,最终成功,讲永不放弃。"}, {"q": "What can we learn about Ben from the passage?", "answer": "A", "options": ["He is patient and never gives up easily.", "He hates making mistakes.", "He gave up after the second try.", "He only builds toys for fun."], "explanation": "''refused to stop'',''kept changing his design'',''twenty tries''可推断他有耐心、不放弃。"}, {"q": "In ''his second try failed too'', the word ''failed'' means ____.", "answer": "A", "options": ["did not work or succeed", "became very fast", "made a loud sound", "cost too much money"], "explanation": "由机器把水洒了、打破花盆可知failed=没成功、失败。"}]'::jsonb, '[{"word": "curious", "cn": "好奇的"}, {"word": "wires", "cn": "电线(wire的复数)"}, {"word": "design", "cn": "设计(方案)"}, {"word": "failure", "cn": "失败"}, {"word": "clapped", "cn": "鼓掌(clap的过去式)"}, {"word": "invent", "cn": "发明"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U3', 'What I like to do after school', 'After a long day at school, I love to relax in my own way. I enjoy reading in the quiet corner of my room, where no one can trouble me. I also like to draw, and I have decided to keep a small notebook for my pictures. On sunny days, I prefer to play outside. My friends and I enjoy playing football in the yard until it gets dark. Some of my classmates like to watch films, but I would rather do something with my hands. My mother wants me to rest too, so I have promised to sleep early. Free time is a gift, and I have learnt to use it well. Choosing to do what you love makes every day brighter.', '放学后我爱做的事(不定式/动名词作宾语)', 123, 1, '[{"q": "What does the writer enjoy doing in the quiet corner?", "answer": "C", "options": ["Playing football.", "Watching films.", "Reading.", "Sleeping."], "explanation": "''I enjoy reading in the quiet corner of my room''。"}, {"q": "What has the writer decided to keep for his pictures?", "answer": "B", "options": ["A camera.", "A small notebook.", "A box.", "A phone."], "explanation": "''I have decided to keep a small notebook for my pictures''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The different things the writer likes to do after school.", "How to play football.", "Why films are boring.", "Where the writer''s room is."], "explanation": "全文讲放学后爱做的事(不定式/动名词作宾语)。"}]'::jsonb, '[{"word": "relax", "cn": "放松"}, {"word": "corner", "cn": "角落"}, {"word": "prefer", "cn": "更喜欢"}, {"word": "gift", "cn": "礼物"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U3', 'Learning to cook', 'This summer, I have decided to learn to cook. At first, I did not enjoy standing in the hot kitchen, and I wanted to give up. But my grandmother kept teaching me with a smile. She showed me how to wash rice and how to cut vegetables. Slowly, I have started to enjoy making simple dishes. I love watching a plain egg turn into a golden, tasty meal. Last week, I finished cooking a whole dinner by myself, and my family enjoyed eating every bit of it. Now I practise cooking every weekend. Cooking needs both care and patience. I have learnt this in the kitchen. Choosing to learn a new skill can be hard at the start, but it brings a joy that is worth all the effort.', '学做饭(不定式/动名词作宾语)', 129, 1, '[{"q": "Who kept teaching the writer to cook?", "answer": "D", "options": ["A friend.", "A teacher.", "A cook in a shop.", "The writer''s grandmother."], "explanation": "''my grandmother kept teaching me with a smile''。"}, {"q": "What did the writer finish cooking last week?", "answer": "A", "options": ["A whole dinner by himself.", "A cup of tea.", "A plate of rice.", "A birthday cake."], "explanation": "''I finished cooking a whole dinner by myself''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to grow vegetables.", "Why kitchens are hot.", "How the writer learnt to enjoy cooking.", "Where the writer''s family lives."], "explanation": "全文讲学做饭并爱上它(不定式/动名词作宾语)。"}]'::jsonb, '[{"word": "kitchen", "cn": "厨房"}, {"word": "dishes", "cn": "菜肴"}, {"word": "tasty", "cn": "美味的"}, {"word": "effort", "cn": "努力"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U3', 'Why I love reading', 'Many of my friends enjoy playing games on their phones, but I prefer to spend my time reading. I started to love books when I was very young. My father enjoyed reading me a story every night, and I could not wait to hear what happened next. Now I like to read on my own. I enjoy meeting brave heroes and visiting faraway lands, all without leaving my chair. Reading has helped me to learn new words and to understand other people. Sometimes I forget to eat because I want to finish a good story. My mother tells me to rest my eyes, and I have promised to read less late at night. Choosing to read has made my world much wider and richer.', '我为什么爱读书(不定式/动名词作宾语)', 124, 1, '[{"q": "What did the writer''s father do every night?", "answer": "D", "options": ["Played games.", "Cooked dinner.", "Watched films.", "Enjoyed reading the writer a story."], "explanation": "''My father enjoyed reading me a story every night''。"}, {"q": "Why does the writer sometimes forget to eat?", "answer": "B", "options": ["Because he is ill.", "Because he wants to finish a good story.", "Because he is playing.", "Because he is tired."], "explanation": "''I forget to eat because I want to finish a good story''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to buy a phone.", "Why games are fun.", "Where the writer sits.", "Why the writer loves reading and how it helps him."], "explanation": "全文讲爱读书的理由(不定式/动名词作宾语)。"}]'::jsonb, '[{"word": "prefer", "cn": "更喜欢"}, {"word": "heroes", "cn": "英雄(hero的复数)"}, {"word": "faraway", "cn": "遥远的"}, {"word": "wider", "cn": "更宽广的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U3', 'My weekend plans', 'I always look forward to the weekend, because I love to do so many things. On Saturday morning, I plan to visit the library, since I enjoy borrowing new books. In the afternoon, my friends want to go to the park, and I have agreed to join them. We enjoy playing basketball and flying kites in the open air. On Sunday, I like to help my parents at home. I have promised to clean my room and to water the plants. In the evening, I prefer to rest quietly and to get ready for Monday. Some people waste their weekends, but I have learnt to use mine well. Choosing how to spend your free time is a small but important skill, and I enjoy making a simple plan each week.', '我的周末计划(不定式/动名词作宾语)', 130, 1, '[{"q": "What does the writer plan to do on Saturday morning?", "answer": "A", "options": ["Visit the library.", "Play basketball.", "Clean the room.", "Water the plants."], "explanation": "''I plan to visit the library''。"}, {"q": "What has the writer promised to do on Sunday?", "answer": "C", "options": ["Fly kites.", "Read all day.", "Clean his room and water the plants.", "Go to the cinema."], "explanation": "''I have promised to clean my room and to water the plants''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to play basketball.", "How the writer plans to spend his weekend.", "Why libraries are quiet.", "Where the park is."], "explanation": "全文讲周末计划(不定式/动名词作宾语)。"}]'::jsonb, '[{"word": "library", "cn": "图书馆"}, {"word": "borrowing", "cn": "借阅"}, {"word": "kites", "cn": "风筝"}, {"word": "plants", "cn": "植物"}]'::jsonb);
-- U4 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U4', 'Great-grandmother''s diary', 'In the year 2095, a girl named Mia learned everything at home. A smooth glass screen on her wall taught her every subject. It told her to sit up straight, asked her to answer questions, and made her repeat words until she got them right. Mia never left her room. She had no classmates, only the calm voice of the screen. Every morning looked just like the one before, quiet and grey and always the same.

One afternoon, while cleaning a dusty cupboard, Mia found a small book with soft yellow pages. Someone wrote inside it by hand. It was her great-grandmother''s diary, almost eighty years old.

Mia began to read. Her great-grandmother wrote about a place called ''school'', a real building full of children. They sat together in one room. They shared lunch, laughed at jokes, and ran in the yard at noon. A kind teacher helped them with their questions and told them wonderful stories. Sometimes they argued, sometimes they helped each other, but they were never alone.

Mia held the little diary close to her chest. She looked around her quiet, empty room and felt something new and cold inside her. The screen asked her to start the next lesson, but she did not move.

''They had so much fun together,'' she said softly. ''I only want a friend to sit beside me too. I want my school to make me feel that way one day.''', '科技与共同学习(不定式作宾补)·改写阿西莫夫《他们曾拥有的乐趣》', 241, 0, '[{"q": "How did Mia learn her lessons at home?", "answer": "B", "options": ["A kind teacher came to her house.", "A glass screen on the wall taught her.", "She read her great-grandmother''s diary.", "She studied with her classmates."], "explanation": "''A smooth glass screen on her wall taught her every subject''。"}, {"q": "What did Mia find in the dusty cupboard?", "answer": "C", "options": ["A new glass screen.", "A box of old toys.", "Her great-grandmother''s handwritten diary.", "A letter from her teacher."], "explanation": "''Mia found a small book... her great-grandmother''s diary''。"}, {"q": "What does the passage mainly want to tell us?", "answer": "D", "options": ["Screens are the best way to learn.", "Old diaries are hard to read.", "Children should stay at home to study.", "Learning together with others brings real joy."], "explanation": "全文对比孤独的屏幕学习与旧日共同学习的乐趣,点明与人共学的快乐。"}, {"q": "How did Mia most probably feel after reading the diary?", "answer": "A", "options": ["Lonely, and wishing for friends to learn with.", "Happy with her screen lessons.", "Angry at her great-grandmother.", "Afraid of the old school."], "explanation": "她感到又新又冷的东西、想要一个朋友,可推断她感到孤独、渴望同伴。"}, {"q": "In the passage, ''classmates'' means ____.", "answer": "B", "options": ["teachers who give lessons", "students who study in the same class", "books on the shelf", "rooms in a school"], "explanation": "由''no classmates, only the... screen''与后文一屋子孩子可推断=同班同学。"}]'::jsonb, '[{"word": "screen", "cn": "屏幕"}, {"word": "subject", "cn": "学科"}, {"word": "classmates", "cn": "同学"}, {"word": "cupboard", "cn": "橱柜"}, {"word": "diary", "cn": "日记"}, {"word": "great-grandmother", "cn": "曾祖母"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U4', 'What my mother wants me to do', 'My mother wants me to grow into a kind and useful person, and she helps me every day. She often asks me to get up early, because she calls the morning the best time to learn. She tells me to finish my homework before I play. When I feel lazy, she encourages me to try my best and never to give up. She also wants me to help at home, so I have learnt to wash the dishes and to keep my room clean. Sometimes I find her rules hard, but her reason is clear: she wants me to become strong. My mother never forces me to do anything without a reason. She always explains why, and she asks me to think for myself. A good parent, I have learnt, teaches a child to stand on their own feet.', '妈妈希望我做的事(不定式作宾补)', 139, 1, '[{"q": "Why does the mother ask the writer to get up early?", "answer": "C", "options": ["To watch films.", "To play games.", "Because the morning is the best time to learn.", "To clean the street."], "explanation": "''she calls the morning the best time to learn''。"}, {"q": "What does the mother do when the writer feels lazy?", "answer": "D", "options": ["She shouts at him.", "She does his homework.", "She sends him to bed.", "She encourages him to try his best."], "explanation": "''she encourages me to try my best and never to give up''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How the writer''s mother guides him to grow well.", "How to wash dishes.", "Why mornings are cold.", "Where the writer studies."], "explanation": "全文讲母亲的引导(不定式作宾补)。"}]'::jsonb, '[{"word": "lazy", "cn": "懒惰的"}, {"word": "encourages", "cn": "鼓励"}, {"word": "forces", "cn": "强迫"}, {"word": "explains", "cn": "解释"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U4', 'A good coach', 'Our football coach, Mr Li, is strict but kind, and he wants every player to do his best. Before each game, he tells us to warm up carefully, so that we all stay safe. During practice, he asks us to pass the ball quickly and to help each other. When we lose, he never allows us to blame our friends. Instead, he encourages us to learn from our mistakes. Mr Li often makes us run ten circles before practice, and he never lets us leave until we put the balls away. He often reminds us to shake hands with the other team after a match. Thanks to him, we have become better players and better friends. A good coach does more than teach us to win; he teaches us to grow into good people.', '一个好教练(不定式作宾补)', 134, 1, '[{"q": "What does Mr Li tell the players to do before each game?", "answer": "B", "options": ["Eat a big meal.", "Warm up carefully.", "Rest at home.", "Buy new shoes."], "explanation": "''he tells us to warm up carefully''。"}, {"q": "What does the coach encourage the players to do after they lose?", "answer": "A", "options": ["Learn from their mistakes.", "Blame each other.", "Give up football.", "Leave the team."], "explanation": "''he encourages us to learn from our mistakes''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to score a goal.", "Why football is hard.", "How a good coach teaches players to grow in many ways.", "Where the team plays."], "explanation": "全文讲好教练育人(不定式作宾补)。"}]'::jsonb, '[{"word": "coach", "cn": "教练"}, {"word": "strict", "cn": "严格的"}, {"word": "blame", "cn": "责怪"}, {"word": "reminds", "cn": "提醒"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U4', 'How my teacher helped me', 'Last year, I was weak in maths, and I often wanted to give up. But my teacher, Ms Chen, did not let me lose hope. She asked me to stay for ten minutes after class, and she helped me to understand each hard problem. She told me to write down every mistake, so that I could learn from it. When I got a right answer, she wanted me to explain it to the class. I felt proud and brave. Ms Chen never allowed me to say ''I can''t''. She always encouraged me to try one more time. Little by little, I have grown to love maths. A good teacher does not only give us knowledge; she helps us to believe in ourselves.', '老师如何帮我(不定式作宾补)', 123, 1, '[{"q": "What did Ms Chen ask the writer to do after class?", "answer": "D", "options": ["Go home at once.", "Clean the room.", "Play football.", "Stay for ten minutes."], "explanation": "''She asked me to stay for ten minutes after class''。"}, {"q": "What did Ms Chen want the writer to do after a right answer?", "answer": "B", "options": ["Rest quietly.", "Explain it to the class.", "Leave the class.", "Write a story."], "explanation": "''she wanted me to explain it to the class''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How a caring teacher helped the writer believe in himself.", "How to solve maths problems.", "Why maths is useless.", "Where Ms Chen lives."], "explanation": "全文讲老师如何帮助建立自信(不定式作宾补)。"}]'::jsonb, '[{"word": "weak", "cn": "薄弱的"}, {"word": "problem", "cn": "难题"}, {"word": "mistake", "cn": "错误"}, {"word": "knowledge", "cn": "知识"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U4', 'Helping my little brother', 'My little brother is only six, and I want him to grow up happy and kind. Every evening, I ask him to put away his toys before bed, and I teach him to say ''please'' and ''thank you''. Sometimes he does not want to listen, but I never force him. Instead, I try to make learning fun. I want him to enjoy reading, so we look at picture books together. When he does something well, I tell him to feel proud of himself. When he makes a mistake, I ask him to try again with a smile. I sometimes let him choose the book, and that makes him want to read more. Helping a younger child has taught me to be patient. To teach is also to learn - I know this now.', '帮助我弟弟(不定式作宾补)', 132, 1, '[{"q": "What does the writer ask his brother to do before bed?", "answer": "C", "options": ["Read a long book.", "Wash the dishes.", "Put away his toys.", "Go outside."], "explanation": "''I ask him to put away his toys before bed''。"}, {"q": "How does the writer help his brother enjoy reading?", "answer": "D", "options": ["By buying him toys.", "By reading alone.", "By telling him to study.", "By looking at picture books together."], "explanation": "''I want him to enjoy reading, so we look at picture books together''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to buy toys.", "How the writer patiently helps his little brother grow.", "Why children cry.", "Where the brother sleeps."], "explanation": "全文讲耐心帮助弟弟(不定式作宾补)。"}]'::jsonb, '[{"word": "toys", "cn": "玩具"}, {"word": "force", "cn": "强迫"}, {"word": "example", "cn": "榜样"}, {"word": "patient", "cn": "有耐心的"}]'::jsonb);
-- U5 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U5', 'Small rules, big reasons', 'Every day we follow many small rules, and each one has a good reason behind it. We may not always notice them, but they keep our lives safe and pleasant.

Think about a simple car ride. We put on a seat belt to protect ourselves if the car stops suddenly. The driver slows down near a school to keep the children safe. People wait for the green light to cross the road without danger. These rules do not exist to trouble us. They exist to save lives. We keep to the right on busy stairs, so no one runs into another person. We wash our hands before meals to stay clean and well.

Good manners work in the same quiet way. We speak softly in a library to let others read in peace. We throw rubbish in the bin to keep our streets clean. We line up at the shop to make things fair for everyone. In order to live together happily, we all give up a little of our own freedom.

Honesty is a rule of the heart. We tell the truth to keep our friends'' trust. We return what we borrow to show respect. If someone breaks these rules, he may win something small today, but he will lose something far greater tomorrow.

So the next time you follow a rule, stop to think about its reason. Behind every good rule stands a wish: to protect, to share, and to care.', '规则与文明(不定式表目的)', 243, 0, '[{"q": "Why do we put on a seat belt in a car?", "answer": "A", "options": ["To protect ourselves if the car stops suddenly.", "To make the car go faster.", "To keep the car clean.", "To follow the driver''s order."], "explanation": "''We put on a seat belt to protect ourselves if the car stops suddenly''。"}, {"q": "According to the passage, why do we speak softly in a library?", "answer": "C", "options": ["To save our own time.", "To make the room warm.", "To let others read in peace.", "To keep the books clean."], "explanation": "''We speak softly in a library to let others read in peace''。"}, {"q": "What is the main idea of the passage?", "answer": "B", "options": ["Rules make our lives hard and boring.", "Every rule exists for a good reason.", "Only drivers need to follow rules.", "Honesty is the only rule that matters."], "explanation": "全文说明每条小规则背后都有好理由——保护、分享、关爱。"}, {"q": "Which idea would the writer probably agree with?", "answer": "A", "options": ["following rules helps everyone live better together", "rules take away all our freedom", "only children need good manners", "breaking rules brings great rewards"], "explanation": "全文肯定规则的意义,可推断作者认为守规则使大家更好地共同生活。"}, {"q": "In the passage, the word ''honesty'' is closest in meaning to ____.", "answer": "A", "options": ["telling the truth and keeping trust", "working very fast", "saving a lot of money", "staying quiet in public"], "explanation": "由''tell the truth'',''keep trust''可推断honesty=诚实。"}]'::jsonb, '[{"word": "seat belt", "cn": "安全带"}, {"word": "rubbish", "cn": "垃圾"}, {"word": "bin", "cn": "垃圾桶"}, {"word": "honesty", "cn": "诚实"}, {"word": "trust", "cn": "信任"}, {"word": "freedom", "cn": "自由"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U5', 'Why we plant trees', 'Every spring, our school plants trees on the hill, and each tree has a purpose. We plant them to make the air cleaner and fresher. We plant them to give birds a home and to bring shade on hot summer days. To hold the soil in place, we plant strong young trees along the river. Last week, my whole class went up the hill to dig holes and to water the small trees. It was hard work, but we sang songs to keep ourselves happy. Our teacher told us a simple truth: to care for a tree is to care for the future. Years from now, we will come back to see how tall they have grown. To plant a tree is to give a gift to those who come after us.', '我们为什么种树(目的状语不定式)', 132, 1, '[{"q": "Why do the students plant strong trees along the river?", "answer": "C", "options": ["To catch fish.", "To build a bridge.", "To hold the soil in place.", "To hide from the sun."], "explanation": "''To hold the soil in place, we plant strong young trees along the river''。"}, {"q": "How did the class keep themselves happy during the hard work?", "answer": "A", "options": ["They sang songs.", "They ate sweets.", "They rested often.", "They went home early."], "explanation": "''we sang songs to keep ourselves happy''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to sing songs.", "Why summer is hot.", "Where the river is.", "The many purposes for which the students plant trees."], "explanation": "全文讲种树的目的(目的状语不定式)。"}]'::jsonb, '[{"word": "purpose", "cn": "目的"}, {"word": "shade", "cn": "树荫"}, {"word": "soil", "cn": "土壤"}, {"word": "dig", "cn": "挖"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U5', 'Getting up early to exercise', 'This year, I have started to get up early to exercise. Every morning, I set my clock at six to give myself enough time. I go to the park to run around the lake and to breathe the fresh morning air. I do this to keep my body strong and my mind clear. At first, it was hard to leave my warm bed. To fight the cold, I put on a coat and told myself to think of the sunrise. Now, running has become my favourite part of the day. Many old people come to the park too, some to dance and some to play chess. We all get up early for the same reason: to make our lives healthier and happier. To start the day well is to win half the battle.', '早起去锻炼(目的状语不定式)', 133, 1, '[{"q": "Why does the writer set the clock at six?", "answer": "B", "options": ["To watch films.", "To give himself enough time.", "To cook breakfast.", "To do homework."], "explanation": "''I set my clock at six to give myself enough time''。"}, {"q": "What do some old people come to the park to do?", "answer": "A", "options": ["To dance or play chess.", "To sleep.", "To sell food.", "To swim."], "explanation": "''some to dance and some to play chess''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to play chess.", "Why parks are big.", "Why and how the writer gets up early to exercise.", "Where the lake is."], "explanation": "全文讲早起锻炼的目的(目的状语不定式)。"}]'::jsonb, '[{"word": "exercise", "cn": "锻炼"}, {"word": "lake", "cn": "湖"}, {"word": "sunrise", "cn": "日出"}, {"word": "chess", "cn": "象棋"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U5', 'Saving money to buy a gift', 'For two months, I have saved my pocket money to buy a special gift. My mother''s birthday is coming, and I want to surprise her. Every week, I put some coins in a small box to keep them safe. To save more, I stopped buying sweets and drinks after school. Sometimes it was hard, but I thought of my mother''s smile to stay strong. Last Sunday, I went to the shop to choose a warm scarf, because she often feels cold in winter. I used all my saved money to pay for it, and I felt very proud. To give a gift with your own money means much more than to buy one with your parents''. The best presents are not the dearest; they are the ones we work hard to give.', '攒钱买礼物(目的状语不定式)', 134, 1, '[{"q": "What did the writer stop buying to save more money?", "answer": "B", "options": ["Books and pens.", "Sweets and drinks.", "Toys and games.", "Shoes and bags."], "explanation": "''I stopped buying sweets and drinks after school''。"}, {"q": "What did the writer buy for his mother?", "answer": "D", "options": ["A book.", "A cake.", "A pair of shoes.", "A warm scarf."], "explanation": "''I went to the shop to choose a warm scarf''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to spend pocket money.", "Why winter is cold.", "How the writer saved money to buy his mother a gift.", "Where the shop is."], "explanation": "全文讲攒钱买礼物(目的状语不定式)。"}]'::jsonb, '[{"word": "pocket money", "cn": "零花钱"}, {"word": "coins", "cn": "硬币"}, {"word": "scarf", "cn": "围巾"}, {"word": "dearest", "cn": "最贵的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U5', 'Why I practise every day', 'I have played the guitar for two years, and I practise every day to get better. In the morning, I play for twenty minutes to warm up my fingers. After school, I practise a new song to make it smooth. It is not always fun; sometimes my fingers hurt, and I want to stop. To keep going, I remember why I started: I love music, and I want to play for my friends. Last month, I practised hard to get ready for our school show. On the day, I stood on the stage to play my favourite song, and everyone clapped. All those quiet hours of practice were worth it. To reach a dream, you need to be ready to work for it, one small step at a time.', '我为什么每天练习(目的状语不定式)', 129, 1, '[{"q": "What does the writer do for twenty minutes in the morning?", "answer": "D", "options": ["Sing a song.", "Read music.", "Rest his hands.", "Play to warm up his fingers."], "explanation": "''I play for twenty minutes to warm up my fingers''。"}, {"q": "Why did the writer practise hard last month?", "answer": "B", "options": ["To sell his guitar.", "To get ready for the school show.", "To rest more.", "To learn to sing."], "explanation": "''I practised hard to get ready for our school show''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["Why the writer practises the guitar every day.", "How to buy a guitar.", "Why shows are long.", "Where the stage is."], "explanation": "全文讲每天练习的目的(目的状语不定式)。"}]'::jsonb, '[{"word": "guitar", "cn": "吉他"}, {"word": "smooth", "cn": "流畅的"}, {"word": "stage", "cn": "舞台"}, {"word": "clapped", "cn": "鼓掌(clap的过去式)"}]'::jsonb);
-- U6 精读
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U6', 'The night of the flood', 'It was raining hard on the night everything changed. In a small mountain village, most people were sleeping quietly in their beds. Lily, a fifteen-year-old girl, was still awake. She was reading by the window while the storm grew louder and louder outside.

Around midnight, she heard a strange, deep sound. She looked out. A wall of water was rushing down the mountain towards the village. The river rose too fast. While the others were dreaming, the flood was coming.

Lily did not wait. She ran into the street, shouting and knocking on every door. ''Wake up! The water is coming! Run to the hill!'' Doors opened one by one. Sleepy families grabbed their children and hurried up the slope. Lily kept running from house to house while the cold water was already touching her feet.

By the time the flood reached the village, everyone was standing safely on the high ground. They watched their homes disappear under the brown water, but no one lost a life. The rain kept falling for hours, but the whole village was safe. Parents held their children close, and the old people thanked the brave girl again and again.

That night, a young girl became the hero of her village. When people later asked her about her fear, she only smiled. ''I was too busy to be afraid,'' she said. ''Everyone was in danger, so I just ran.''

The villagers have never forgotten her. Every year, on that day, they still tell her brave story.', '灾难与勇气(过去进行时)', 253, 0, '[{"q": "What was Lily doing around midnight when others were sleeping?", "answer": "B", "options": ["She was already asleep in bed.", "She was reading by the window.", "She was running up the hill.", "She was closing every door."], "explanation": "''She was reading by the window while the storm grew louder''。"}, {"q": "How did Lily warn the villagers?", "answer": "C", "options": ["She rang a big bell on the hill.", "She called them on the phone.", "She ran in the street, shouting and knocking on doors.", "She turned on all the lights."], "explanation": "''She ran into the street, shouting and knocking on every door''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["A terrible rainstorm in summer.", "How to build a house on high ground.", "A brave girl who saved her village from a flood.", "Why rivers rise in the mountains."], "explanation": "全文讲Lily在洪水之夜勇敢叫醒全村,救了大家。"}, {"q": "We can infer from Lily''s words that she ____.", "answer": "A", "options": ["cared more about others than about her own fear", "was not afraid of anything at all", "wanted people to praise her", "enjoyed running in the rain"], "explanation": "''too busy to be afraid'',''Everyone was in danger, so I just ran''可推断她把他人安危放在自己害怕之上。"}, {"q": "In the passage, ''flood'' means ____.", "answer": "A", "options": ["a great amount of water covering the land", "a strong cold wind", "a tall mountain", "a quiet river in summer"], "explanation": "由水从山上奔涌、淹没房屋可推断flood=洪水。"}]'::jsonb, '[{"word": "flood", "cn": "洪水"}, {"word": "rushing", "cn": "奔涌(rush的现在分词)"}, {"word": "slope", "cn": "斜坡"}, {"word": "grabbed", "cn": "抓住(grab的过去式)"}, {"word": "villager", "cn": "村民"}, {"word": "brave", "cn": "勇敢的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U6', 'When the rain came', 'Yesterday afternoon, the weather changed very fast. At three o''clock, the sun was shining, and I was walking home from school with my friends. We were laughing and talking about the weekend. Suddenly, dark clouds came, and a strong wind began to blow. While we were crossing the square, big drops of rain started to fall. We were not carrying umbrellas, so we ran to a shop to hide. Inside, an old man was reading a newspaper, and a woman was buying bread. They smiled at us kindly. We waited there while the rain was falling hard outside. Ten minutes later, the sky cleared, and the sun came out again. We walked home wet but happy. It was a small adventure on an ordinary day.', '下雨时我在做什么(过去进行时)', 126, 1, '[{"q": "What was the writer doing at three o''clock?", "answer": "B", "options": ["Sleeping at home.", "Walking home from school.", "Reading a newspaper.", "Buying bread."], "explanation": "''I was walking home from school with my friends''。"}, {"q": "Why did the friends run to a shop?", "answer": "D", "options": ["To buy bread.", "To meet the old man.", "Because school was over.", "Because they were not carrying umbrellas and the rain fell."], "explanation": "''We were not carrying umbrellas, so we ran to a shop to hide''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["A small rainy-day adventure on the way home.", "How to buy an umbrella.", "Why clouds are dark.", "Where the shop is."], "explanation": "全文讲雨中回家的小插曲(过去进行时)。"}]'::jsonb, '[{"word": "shining", "cn": "照耀"}, {"word": "square", "cn": "广场"}, {"word": "umbrellas", "cn": "雨伞"}, {"word": "adventure", "cn": "冒险"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U6', 'A busy morning', 'This morning, our house was busier than a market. At seven o''clock, everyone was doing something. My mother was cooking breakfast in the kitchen, and the room was full of the smell of eggs. My father was looking for his keys, but he could not find them. My little sister was crying because she could not tie her shoes. I was packing my school bag while I was eating a piece of bread. The radio was playing loud music, and the dog was running around our feet. For a few minutes, no one could hear anyone else. Then, at last, we all left the house together. As I walked to school, everything felt quiet and calm. A busy morning is tiring, but it is also full of warm family life.', '忙碌的早晨(过去进行时)', 131, 1, '[{"q": "What was the mother doing at seven o''clock?", "answer": "C", "options": ["Looking for keys.", "Tying shoes.", "Cooking breakfast.", "Playing music."], "explanation": "''My mother was cooking breakfast in the kitchen''。"}, {"q": "Why was the little sister crying?", "answer": "B", "options": ["She was hungry.", "She could not tie her shoes.", "She was ill.", "She lost her bag."], "explanation": "''My little sister was crying because she could not tie her shoes''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to cook eggs.", "Why dogs run.", "Where the keys were.", "A busy but warm family morning."], "explanation": "全文讲忙碌温暖的早晨(过去进行时)。"}]'::jsonb, '[{"word": "keys", "cn": "钥匙"}, {"word": "tie", "cn": "系(鞋带)"}, {"word": "radio", "cn": "收音机"}, {"word": "calm", "cn": "平静的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U6', 'The day the lights went out', 'One evening last winter, our whole street lost its power. We were having dinner when the lights suddenly went out. At first, my little brother was afraid, but my father lit some candles, and the room grew warm and golden. We could not watch television or use our phones, so we did something we did not often do. My mother was telling old stories from her childhood, and we were all listening quietly. My brother was drawing shadows on the wall with his hands. Outside, the stars were shining more brightly than ever. For two hours, while the power was off, our family talked and laughed together. When the lights came back, we almost felt sorry. That dark evening gave us something bright: time together, without any screens.', '停电那天(过去进行时)', 128, 1, '[{"q": "What were the family doing when the lights went out?", "answer": "A", "options": ["Having dinner.", "Sleeping.", "Watching television.", "Playing outside."], "explanation": "''We were having dinner when the lights suddenly went out''。"}, {"q": "What was the mother doing during the power cut?", "answer": "C", "options": ["Cooking food.", "Reading a book.", "Telling old stories from her childhood.", "Looking for candles."], "explanation": "''My mother was telling old stories from her childhood''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to make candles.", "Why stars shine.", "Where the street is.", "How a power cut brought a family closer together."], "explanation": "全文讲停电让家人更亲近(过去进行时)。"}]'::jsonb, '[{"word": "power", "cn": "电"}, {"word": "candles", "cn": "蜡烛"}, {"word": "shadows", "cn": "影子"}, {"word": "screens", "cn": "屏幕"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (8, 'junior_fltrp', 'wy8A', 'U6', 'While I was walking home', 'Last Friday, something strange happened while I was walking home. The sun was setting, and the street was quiet. As I was passing the old park, I heard a soft sound near a tree. A small kitten was sitting alone in the grass, crying for help. It was shivering, because the evening was growing cold. I did not know what to do at first. While I was thinking, an old woman came by. She was carrying a bag of food, and she smiled at me kindly. Together, we gave the kitten some milk and kept it warm. The old woman wanted a pet of her own, so she took the kitten home. As I walked on, I felt happy. Sometimes the best moments come when we are not looking for them at all.', '回家路上(过去进行时)', 133, 1, '[{"q": "What was the kitten doing near the tree?", "answer": "C", "options": ["Sleeping.", "Playing with a ball.", "Sitting alone and crying for help.", "Eating food."], "explanation": "''A small kitten was sitting alone in the grass, crying for help''。"}, {"q": "What was the old woman carrying?", "answer": "B", "options": ["An umbrella.", "A bag of food.", "A book.", "A cat basket."], "explanation": "''She was carrying a bag of food''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How the writer helped a lost kitten on the way home.", "How to feed a cat.", "Why evenings are cold.", "Where the park is."], "explanation": "全文讲回家路上救小猫(过去进行时)。"}]'::jsonb, '[{"word": "setting", "cn": "(太阳)落下"}, {"word": "kitten", "cn": "小猫"}, {"word": "shivering", "cn": "发抖"}, {"word": "milk", "cn": "牛奶"}]'::jsonb);

-- 断言
DO $$
DECLARE tot int; intn int; extn int; qbad int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A';
  IF tot<>30 THEN RAISE EXCEPTION 'total=% 期望30', tot; END IF;
  SELECT count(*) INTO intn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A' AND difficulty=0;
  IF intn<>6 THEN RAISE EXCEPTION '精读(diff0)=% 期望6', intn; END IF;
  SELECT count(*) INTO extn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A' AND difficulty=1;
  IF extn<>24 THEN RAISE EXCEPTION '泛读(diff1)=% 期望24', extn; END IF;
  SELECT count(*) INTO qbad FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A'
    AND NOT ((difficulty=0 AND jsonb_array_length(questions)=5) OR (difficulty=1 AND jsonb_array_length(questions)=3));
  IF qbad<>0 THEN RAISE EXCEPTION '题数不符(精读5/泛读3)的篇=%', qbad; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A' GROUP BY unit HAVING count(*)<>5) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠5篇(1精读+4泛读)的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy8A 阅读 % 篇(精读6+泛读24)· 6单元各5', tot;
END $$;

COMMIT;

SELECT unit, difficulty, count(*) 篇, min(jsonb_array_length(questions))||'-'||max(jsonb_array_length(questions)) 题数 FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy8A' GROUP BY unit,difficulty ORDER BY unit,difficulty DESC;